window.addEventListener('DOMContentLoaded',function(){document.querySelectorAll('.accordion').forEach(item=>{Tabs.create(item,{accordion:true,itemClass:'accordion-item',headerClass:'accordion-header',contentClass:'accordion-content',activeClass:'active',multipleOpen:false,openFirstAccordionItem:false,});});document.querySelectorAll('#accordionwrapper').forEach(item=>{Tabs.create(item,{itemClass:'st-accordion',buttonClass:'accordion-tab-button',activeClass:'active',contentClass:'accordion',openFirstAccordionItem:true,});});});;